UPDATE iam_user_role
SET deleted = 1, deleted_at = NOW(3), updated_at = NOW(3),
    updated_by = COALESCE(#{actorId}, 0), version = version + 1
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND deleted = 0

UPDATE iam_user_role
SET deleted = 1, deleted_at = NOW(3), updated_at = NOW(3),
    updated_by = COALESCE(#{actorId}, 0), version = version + 1
WHERE tenant_id = #{tenantId}
  AND role_id = #{roleId}
  AND deleted = 0
